\begin{equation*}
\left\{
\begin{array}{ll}
\Delta u + \lambda (1 + \beta u^2) f(u) = 0, \quad \mbox{in} \ \Omega, \\
\frac{\partial u}{\partial n} = 0, \quad \mbox{on} \ \partial \Omega.
\end{array}
\right.
\end{equation*}
